function renderComposerVariables(){const root=$('#composer-variables');if(!root)return;const variables=variablesForStep(composer.document.steps,getSelectedStep(),composer.document.inputs);root.innerHTML='<div class="variable-section-title">当前步骤可用变量</div><p class="note">先点击参数输入框，再选变量插入。分支内部的变量不会自动带到外层。</p>'+variables.map(variable=>`<button class="composer-variable" data-compose-variable="${esc(variable.name)}"><span>{ }</span><div><strong>${esc(variable.name)}</strong><small>${esc(variable.kind)} · ${esc(variable.source)}</small></div></button>`).join('');root.querySelectorAll('[data-compose-variable]').forEach(button=>button.onclick=()=>{const focused=composer.focused;if(!focused||focused.input.readOnly||!document.contains(focused.input)){toast('先点击需要插入变量的参数输入框');return}insertVariable(focused.input,variables.find(variable=>variable.name===button.dataset.composeVariable),focused.field,focused.step)})}
async function validateComposer(){
 const errors=validateActionDocument(composer.document,composer.kind);if(errors.length)return errors;
 const document=structuredClone(data);let owner;
 // The action editor also validates new rules whose gesture is not saved yet.
 if(composer.kind==='rule'){owner=structuredClone(draft);owner.gestureId||='';owner.steps=structuredClone(composer.document.steps);const index=document.rules.findIndex(rule=>rule.id===owner.id);if(index<0)document.rules.push(owner);else document.rules[index]=owner;}
 else{owner=structuredClone(composer.document);const index=document.workflows.findIndex(workflow=>workflow.id===owner.id);if(index<0)document.workflows.push(owner);else document.workflows[index]=owner;}
 try{
  const checked=await backend.validate(document);const prefix=(composer.kind==='rule'?'rules.':'workflows.')+owner.id;
  const relevant=checked.filter(error=>error.path.startsWith(prefix+'.steps.')||error.path===prefix||composer.kind==='workflow'&&error.path.startsWith(prefix));
  if(relevant.length){const selected=allSteps(composer.document.steps).find(step=>relevant[0].path.includes('.steps.'+step.uid));if(selected){composer.selected=selected.uid;renderComposerTree();renderComposerParameters();renderComposerVariables();globalThis.document.querySelector(`[data-step-uid="${selected.uid}"]`)?.scrollIntoView({block:'nearest'});}}
  return relevant.map(error=>{const step=allSteps(composer.document.steps).find(step=>error.path.includes('.steps.'+step.uid));return (step?types[step.type]+'：':'')+error.message;});
 }catch(error){
  const selected=allSteps(composer.document.steps).find(step=>step.uid===error.stepId);
  if(selected){composer.selected=selected.uid;renderComposerTree();renderComposerParameters();renderComposerVariables();globalThis.document.querySelector(`[data-step-uid="${selected.uid}"]`)?.scrollIntoView({block:'nearest'});}
  return [String(error)];
 }
}
