function validateActionDocument(document,kind){const errors=[];if(kind==='workflow'&&!document.name.trim())errors.push('请填写动作名称');if(!document.steps.length)errors.push('至少添加一个步骤');return errors}
async function saveComposerAsWorkflow(){const editing=composer;const errors=await validateComposer();if(composer!==editing)return;if(errors.length){$('#composer-errors').hidden=false;$('#composer-errors').innerHTML=errors.map(error=>`<p>${esc(error)}</p>`).join('');return}const dialog=$('#workflow-dialog');dialog.innerHTML=`<form id="save-workflow-form"><div class="dialog-header"><h2>另存为可复用动作</h2><button type="button" id="close-save-workflow" aria-label="关闭另存动作">×</button></div><div class="dialog-body"><label class="field"><span>动作名称</span><input name="name" aria-label="新动作名称" value="${esc(composer.document.name+' 动作')}" required></label><label class="field"><span>说明</span><textarea name="description" aria-label="新动作说明" rows="2" placeholder="这组操作会完成什么？"></textarea></label><label class="row"><input type="checkbox" name="bind" checked>将当前编排改为引用这个动作</label><p class="note">保存全部步骤。动作独立于窗口条件，可供其他规则引用。</p><p id="save-workflow-error" class="danger" role="alert"></p></div><div class="dialog-footer"><button type="button" id="cancel-save-workflow">取消</button><button class="primary" type="submit">保存动作</button></div></form>`;dialog.showModal();$('#close-save-workflow').onclick=$('#cancel-save-workflow').onclick=()=>dialog.close();$('#save-workflow-form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),name=String(form.get('name')).trim();if(data.workflows.some(workflow=>workflow.name===name)){$('#save-workflow-error').textContent='已有同名动作，请换一个名称';return}const workflow={id:'workflow-'+Date.now(),name,description:form.get('description'),inputs:[],outputs:[],steps:composer.document.steps.map(copyStep)};data.workflows.push(workflow);await persist();if(form.get('bind')){const call=newStep('flow.call');call.workflowId=workflow.id;call.value=workflow.name;call.inputValues={};ensureStepIds([call]);composer.document.steps=[call];composer.selected=call.uid;composerChanged()}dialog.close();renderComposer();toast('动作已保存，规则仍需应用编排并保存')};}

