 let filter='all';
 function list(){const rules=data.rules.filter(r=>(scope==='全部'||(r.applicationId||'')===scope)&&(filter==='all'||r.enabled===(filter==='on'))&&`${r.name} ${JSON.stringify(r.steps)}`.toLowerCase().includes(query.toLowerCase()));$('#rule-list').innerHTML='<div class="list-head"><span>轨迹与规则</span><span>作用范围 / 启用</span></div>'+rules.map(r=>`<div class="rule-row ${r.id===selected?'selected':''} ${r.enabled?'':'disabled'}" data-id="${r.id}"><button class="gesture-icon" aria-label="编辑 ${esc(r.name)}">${pathSVG(r.path)}</button><div class="rule-copy"><strong>${esc(r.name)}</strong><small>右键${r.modifier!=='无'?' + '+esc(r.modifier):''} · ${esc(r.steps.length===1?stepSummary(r.steps[0]):r.steps.length+' 个动作步骤')}</small></div><span class="chip ${r.scope==='全局'?'':'purple'}">${esc(r.scope)}${r.titleMatch?.value?' · 标题':''}</span>${switchHTML(r.enabled,'启用 '+r.name,`data-toggle="${r.id}"`)}</div>`).join('')+(rules.length?'':'<div class="empty">没有匹配的规则<br>换个关键词，或新建一条规则。</div>');$('#list-count').textContent=`${rules.length} 条规则 · ${rules.filter(r=>r.enabled).length} 条已启用`;
 $('#rule-list').querySelectorAll('[data-id]').forEach(row=>{row.onclick=e=>{if(e.target.closest('.switch'))return;const choose=()=>{selected=row.dataset.id;draft=structuredClone(data.rules.find(r=>r.id===selected));dirty=false;list();renderEditor()};dirty?askConfirm('放弃当前未保存的修改？',choose):choose()}});
 $('#rule-list').querySelectorAll('[data-toggle]').forEach(el=>el.onchange=async ()=>{const r=data.rules.find(r=>r.id===el.dataset.toggle);if(el.checked&&data.rules.some(other=>other.id!==r.id&&other.enabled&&rulesConflict(other,r))){el.checked=false;showMessage('规则触发冲突','已有启用规则使用相同的窗口条件、手势与辅助键。请先调整条件，或停用原规则。');return}r.enabled=el.checked;if(draft?.id===r.id)draft.enabled=r.enabled;await persist();list()});}
 $('#search').oninput=e=>{query=e.target.value;list()};$('#scope').onchange=e=>{scope=e.target.value;list()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('selected',x===b));list()});
