function strokeLength(points){return points.slice(1).reduce((sum,p,i)=>sum+Math.hypot(p[0]-points[i][0],p[1]-points[i][1]),0)}
function pathSVG(points){if(points.length<2)return '<span class="muted">—</span>';const xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);const span=Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...ys)-Math.min(...ys),1),pad=span*.12;const x=Math.min(...xs)-pad,y=Math.min(...ys)-pad,w=Math.max(...xs)-x+pad,h=Math.max(...ys)-y+pad;return `<svg viewBox="${x} ${y} ${Math.max(w,span*.25)} ${Math.max(h,span*.25)}" role="img" aria-label="录制的自由手势轨迹"><polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#6262cf" stroke-width="${span*.025}" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${points[0][0]}" cy="${points[0][1]}" r="${span*.032}" fill="#6262cf"/><circle cx="${points.at(-1)[0]}" cy="${points.at(-1)[1]}" r="${span*.025}" fill="white" stroke="#6262cf" stroke-width="${span*.015}"/></svg>`}
