   const result=await backend.testTextRule({applicationId,beforeCursor,trigger,composing,password:false,terminal:false});
   if(token!==generation||!input.isConnected||composing||input.value!==before||input.selectionStart!==end||input.selectionEnd!==end||$('#snippet-test-scope').value!==target)return;
   if(!result){$('#expand-status').textContent='没有匹配的已保存规则';return}
